-- GENERATED by scripts/render_identity_views.py from mcp_calls_deloop — do not hand-edit; edit the module and re-render.

CREATE OR REPLACE VIEW mcp_calls_identity AS
 SELECT id,
    tool_name,
    platform,
    client_name,
    success,
    response_time_ms,
    ip_address,
    user_agent,
    created_at,
    session_id,
    TRIM(BOTH FROM split_part(ip_address, ',', 1)) AS client_ip,
    -- agent grain guard (2026-07-19): a Cloudflare-POP first hop is NOT an
    -- agent identity — NULL it so COUNT(DISTINCT agent_id) never counts POPs.
    CASE WHEN TRIM(BOTH FROM split_part(ip_address, ',', 1)) ~ '^(104\.(1[6-9]|2[0-7])\.|172\.(6[4-9]|7[01])\.|162\.15[89]\.|141\.101\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.|108\.162\.(19[2-9]|2[0-4][0-9]|25[0-5])\.|173\.245\.(4[89]|5[0-9]|6[0-3])\.|188\.114\.(9[6-9]|10[0-9]|11[01])\.|190\.93\.(24[0-9]|25[0-5])\.|197\.234\.24[0-3]\.|198\.41\.(12[89]|1[3-9][0-9]|2[0-4][0-9]|25[0-5])\.|131\.0\.7[2-5]\.|103\.21\.24[4-7]\.|103\.22\.20[0-3]\.|103\.31\.[4-7]\.)' THEN NULL
         ELSE md5(TRIM(BOTH FROM split_part(ip_address, ',', 1))) END AS agent_id,
    ip_address IS NOT NULL AND ip_address <> '' AND TRIM(BOTH FROM split_part(ip_address, ',', 1)) !~ '^(10\.|127\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.|169\.254\.|100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.|::1|fc|fd|0\.0\.0\.0|$)' AS is_public_ip,
    (((CASE
        -- ★2026-07-28: "mcp" is the name of the PROTOCOL, not of a client.
        -- 4,283 calls/7d arrive with clientInfo.name="mcp", and the verbatim
        -- branch below trusted it as an identity — which is how 87% of call
        -- volume ended up in a bucket we described as "unattributed". It was
        -- never unattributed; it was one generic string being read as a name.
        --
        -- Trusting it also PRE-EMPTED the internal-dchub branch, so our own
        -- probes (dchub-fixwave-probe/1.0 and friends, 1,072 calls / 132
        -- agent_ids in 7d) were classified 'mcp' rather than as self-traffic.
        -- PROBE_PLATFORMS could not exclude them because they never reached it.
        --
        -- NOTE the trap this avoids. The obvious fix — "don't trust it, fall
        -- through to the UA branches" — sends every one of these rows to
        -- `user_agent ILIKE '%node%'` => 'node-script', which IS in
        -- PROBE_PLATFORMS. That would have silently deleted our LARGEST REAL
        -- COHORT (3,164 calls / 63 agents of genuine agent work: 35 distinct
        -- tools, 11-50 calls per episode, zero single-call episodes) and read
        -- as a traffic collapse. A generic client_name means "unnamed MCP
        -- client", NOT "someone's node script hitting the REST API", so these
        -- rows get their own real bucket and never touch the node heuristics.
        --
        -- Verified against the replica before shipping: the split yields
        -- mcp-generic-client 3,212 calls/66 agents (real, preserved — matches
        -- the 3,207/65 the reach endpoint already reports) and internal-dchub
        -- 1,072/132 (probe, correctly excluded). Headline real numbers do not
        -- move; the classification stops being accidentally right.
        WHEN LOWER(COALESCE(client_name, '')) IN ('mcp', 'mcp-client', 'client', 'default')
             AND (user_agent ILIKE '%dchub-%' OR user_agent ILIKE '%dchubhealer%'
                  OR user_agent ILIKE '%brain-v2-headless%' OR user_agent ILIKE '%brain-radar%'
                  OR user_agent ILIKE '%uptimerobot%' OR user_agent ILIKE '%DCHub/%'
                  OR user_agent ILIKE '%Globeholder-%')
            THEN 'internal-dchub'
        WHEN LOWER(COALESCE(client_name, '')) IN ('mcp', 'mcp-client', 'client', 'default')
            THEN 'mcp-generic-client'
        WHEN NULLIF(LOWER(client_name), '') IS NOT NULL
             AND client_name !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN LOWER(client_name)
        WHEN user_agent ILIKE '%dchub-%' OR user_agent ILIKE '%dchubhealer%'
            OR user_agent ILIKE '%brain-v2-headless%' OR user_agent ILIKE '%brain-radar%'
            OR user_agent ILIKE '%uptimerobot%'
            THEN 'internal-dchub'
        WHEN user_agent ILIKE '%@modelcontextprotocol/sdk%'
            OR user_agent ILIKE '%modelcontextprotocol%'
            THEN 'mcp-sdk'
        WHEN user_agent ILIKE '%mcp-inspector%'
            THEN 'mcp-inspector'
        WHEN user_agent ILIKE '%n8n%'
            THEN 'n8n'
        WHEN user_agent ILIKE '%smithery%'
            THEN 'smithery'
        WHEN user_agent ILIKE '%chatgpt%' OR user_agent ILIKE '%openai%'
            THEN 'chatgpt'
        WHEN user_agent ILIKE '%claude%' OR user_agent ILIKE '%anthropic%'
            THEN 'claude'
        WHEN user_agent ILIKE '%perplexity%'
            THEN 'perplexity'
        WHEN user_agent ILIKE '%gemini%' OR user_agent ILIKE '%googleother%'
            THEN 'gemini'
        WHEN user_agent ILIKE '%groq%'
            THEN 'groq'
        WHEN user_agent ILIKE '%cursor%'
            THEN 'cursor'
        WHEN user_agent ILIKE '%windsurf%' OR user_agent ILIKE '%codeium%'
            THEN 'windsurf'
        WHEN user_agent ILIKE '%continue%'
            THEN 'continue.dev'
        WHEN user_agent ILIKE '%cody%' OR user_agent ILIKE '%sourcegraph%'
            THEN 'sourcegraph-cody'
        WHEN user_agent ILIKE '%copilot%'
            THEN 'github-copilot'
        WHEN user_agent ILIKE '%cline%'
            THEN 'cline'
        WHEN user_agent ILIKE '%phind%'
            THEN 'phind'
        WHEN user_agent ILIKE '%you.com%' OR user_agent ILIKE '%youbot%'
            THEN 'you.com'
        WHEN user_agent ILIKE '%meta-external%' OR user_agent ILIKE '%llama%'
            THEN 'meta-ai'
        WHEN user_agent ILIKE '%applebot-extended%'
            THEN 'apple-intelligence'
        WHEN user_agent ILIKE '%curl%'
            THEN 'curl'
        WHEN user_agent ILIKE '%python%' OR user_agent ILIKE '%requests%'
            THEN 'python-script'
        WHEN user_agent ILIKE '%node-fetch%' OR user_agent ILIKE '%undici%'
            OR user_agent ILIKE '%axios%' OR user_agent ILIKE '%got/%'
            THEN 'node-http-client'
        WHEN user_agent ILIKE '%node%'
            THEN 'node-script'
        WHEN user_agent ILIKE '%postman%'
            THEN 'postman'
        WHEN user_agent ILIKE '%insomnia%'
            THEN 'insomnia'
        ELSE 'unknown'
    END NOT IN ('canon','curl','dchub-canon-probe','insomnia','internal-dchub','node-http-client','node-script','postman','python-script','verify')) AND (COALESCE(LOWER(platform), '') NOT IN ('acme-siting-agent','agentpulse','capwall2','catalog-sync','clawith','dbg','dchubhealer','f5r','final','fix2-v2','full','fv','manifest-mirror','mcp-gateway-registry','mcp-probe','mcp-rugpull-research','mcp-vouch','mcpexplorerbot','mcpindex-trust','mcpqueen-grader','mcpscoringengine','p','pipeline_mcp','probe','qa','qa-mozilla','raw','rev','reviewer-sim','t','test','v','value-harness','verify','vinline','watchdog','yellowmcp-health') AND COALESCE(LOWER(platform), '') NOT LIKE '%dchub%' AND COALESCE(LOWER(platform), '') NOT LIKE '%verify%' AND COALESCE(LOWER(platform), '') NOT LIKE '%probe%' AND COALESCE(LOWER(platform), '') NOT LIKE '%audit%' AND COALESCE(LOWER(platform), '') NOT LIKE '%harness%' AND COALESCE(LOWER(platform), '') NOT LIKE '%test%' AND COALESCE(LOWER(platform), '') NOT LIKE '%check%' AND COALESCE(LOWER(platform), '') NOT LIKE '%diag%' AND COALESCE(LOWER(platform), '') NOT LIKE '%sweep%' AND COALESCE(LOWER(platform), '') NOT LIKE '%registry%' AND COALESCE(LOWER(platform), '') NOT LIKE '%catalog%' AND COALESCE(LOWER(platform), '') NOT LIKE '%mirror%' AND COALESCE(LOWER(platform), '') NOT LIKE '%watchdog%' AND COALESCE(LOWER(platform), '') NOT LIKE '%health%' AND COALESCE(LOWER(platform), '') NOT LIKE '%crawler%' AND COALESCE(LOWER(platform), '') NOT LIKE '%scanner%' AND COALESCE(LOWER(platform), '') NOT LIKE '%uptime%' AND COALESCE(LOWER(platform), '') NOT LIKE '%validator%' AND (COALESCE(LOWER(platform), '') = '' OR LENGTH(COALESCE(LOWER(platform), '')) > 2)) AND COALESCE(user_agent,'') !~* '(python-httpx|python-urllib|urllib|curl/|wget|libwww|node-fetch|undici|axios|got/|go-http|okhttp|java/|requests/|aiohttp|scrapy|httpie|restsharp|dchub-|dchub/|dchubhealer|self.?heal|value-harness|regression|brain-radar|brain-v2-headless|render-verify|uptimerobot|chrome/1[2-9][0-9]\.0 safari|smoke test|attribution-test|-qa/|qa-judge-probe|acme-siting-agent|reviewer-sim|dc-hub|starterpack-verify/|starterpack-audit/|order-verify/|keyless-audit-probe/)' AND TRIM(BOTH FROM split_part(COALESCE(ip_address, ''), ',', 1)) NOT IN ('127.0.0.1', '::1', 'localhost'))
    AND TRIM(BOTH FROM split_part(ip_address, ',', 1)) !~ '^(162\.220\.232\.|152\.55\.17[67]\.|50\.18\.85\.20$)'
    AND NOT (TRIM(BOTH FROM split_part(ip_address, ',', 1)) ~ '^54\.' AND COALESCE(user_agent, '') = 'node')
    ) AS is_real_external
   FROM mcp_tool_calls;

CREATE OR REPLACE VIEW mcp_agent_retention_30d AS
 SELECT agent_id,
    min(client_ip) AS client_ip,
    min(created_at) AS first_call,
    max(created_at) AS last_call,
    count(*) AS calls,
    count(DISTINCT created_at::date) AS active_days,
    count(DISTINCT session_id) AS sessions,
    count(DISTINCT created_at::date) >= 2 AS returned_2nd_day
   FROM mcp_calls_identity
  WHERE created_at >= (now() - '30 days'::interval) AND is_public_ip AND is_real_external
    AND agent_id IS NOT NULL
  GROUP BY agent_id;
